1	#!/usr/bin/env node
2	// 从真实 CSV 复算并导出完整 campaign；不执行后端，不改原始记录。
3	import { readFileSync, writeFileSync, mkdirSync, copyFileSync, existsSync } from 'node:fs';
4	import { resolve, basename, relative } from 'node:path';
5	import { createHash } from 'node:crypto';
6	import { paths, readIndex } from '../bridge/lib/store.js';
7	import { loadCsv } from '../bridge/backends/replay.js';
8	import { computeMetrics } from '../bridge/lib/metrics.js';
9	import { diagnose } from '../bridge/lib/diagnostics.js';
10	import {simConditions} from '../bridge/lib/sim-options.js';
11	import {normalizeSimController} from '../bridge/lib/sim-controller.js';
12	
13	try {
14	  const args=process.argv.slice(2), flags={};
15	  for(let i=0;i<args.length;i+=2) {
16	    if(!['--campaign','--out'].includes(args[i]) || !args[i+1] || args[i+1].startsWith('--') || flags[args[i]])
17	      throw new Error('用法: --campaign <标识> [--out <新目录>]');
18	    flags[args[i]]=args[i+1];
19	  }
20	  const campaign=flags['--campaign'];
21	  if(!/^[A-Za-z0-9_-]{1,80}$/.test(campaign ?? '')) throw new Error('缺少或非法 campaign');
22	  const records=readIndex().filter(r=>r.campaign===campaign);
23	  if(!records.length) throw new Error('campaign 没有记录');
24	  const ids=new Set();
25	  let previous=null;
26	  for(const r of records) {
27	    if(r.backend!=='sim' || r.evaluation?.version!=='2.3') throw new Error('本工具只验证 v2.3 sim campaign');
28	    if(!r.runId || ids.has(r.runId)) throw new Error('runId 缺失或重复');
29	    if((r.decision?.parent??null)!==(previous?.runId??null)) throw new Error('parent 不属于此前的本次记录');
30	    ids.add(r.runId);previous=r;
31	    if(!r.csv || basename(r.csv)!==r.csv) throw new Error('CSV 文件名非法');
32	    const file=resolve(paths.runs,r.csv);
33	    if(createHash('sha256').update(readFileSync(file)).digest('hex')!==r.csvHash) throw new Error(`CSV hash 不符: ${r.runId}`);
34	    const actual=computeMetrics(loadCsv(file),{...r.evaluation.metrics,weights:r.evaluation.weights});
35	    for(const k of ['fail','converged','n','j','overshoot','settlingMs','ssErr','osc','energy']) {
36	      const normalized=v=> typeof v==='number' && !Number.isFinite(v)?(Number.isNaN(v)?null:String(v)):v;
37	      if(normalized(actual[k])!==r.metrics[k]) throw new Error(`指标 ${k} 不符: ${r.runId}`);
38	    }
39	  }
40	  if(new Set(records.map(r=>r.meta.sim.modelVersion??'legacy-1')).size!==1) throw Error('仿真模型版本不一致');

40	  if(new Set(records.map(r=>r.meta.sim.modelVersion??'legacy-1')).size!==1) throw Error('仿真模型版本不一致');
41	  const controllers=new Set(records.map(r=>JSON.stringify(normalizeSimController(r.meta.sim.controller??{}))));
42	  if(controllers.size!==1) throw Error('campaign 不允许混用 simController');
43	  const hashes=new Set(records.map(r=>r.sourceHash));
44	  for(const r of records.filter(r=>r.diagnostics)) {
45	    const d=diagnose(loadCsv(resolve(paths.runs,r.csv)),{tolerance:r.metrics.tol??r.evaluation.metrics.tolFloor,
46	      holdMs:r.evaluation.metrics.settleHoldMs,disturbanceAtMs:r.meta.sim.disturbanceEvent?.atMs??null});
47	    if(JSON.stringify(d)!==JSON.stringify(r.diagnostics)) throw Error(`诊断不符: ${r.runId}`);
48	  }
49	  if(hashes.size!==1 || !/^[a-f0-9]{64}$/.test(records[0].sourceHash)) throw new Error('campaign 源码身份不一致');
50	  const searches=records.filter(r=>r.decision.purpose==='search');
51	  const c=r=>simConditions({durationMs:r.durationMs,target:r.target,x0:r.meta.sim.x0,seed:r.meta.sim.seed,disturbance:r.meta.sim.disturbance,simProfile:r.meta.sim.simProfile,simController:r.meta.sim.controller});
52	  const conditions=r=>JSON.stringify({...c(r),evaluation:r.evaluation});
53	  if(new Set(searches.map(conditions)).size>1) throw new Error('搜索工况不一致，不允许混排');
54	  const plan=records[0].experimentPlan??null;
55	  const validation=records.filter(r=>r.decision.purpose==='robustness');
56	  if(records.some(r=>JSON.stringify(r.experimentPlan??null)!==JSON.stringify(plan))) throw Error('plan身份不一致');
57	  if(plan) {
58	    if(searches.length>plan.maxSearch || validation.length!==plan.validation.length) throw Error('预算超限或验证场景未完成');
59	    if(searches.some(r=>JSON.stringify(c(r))!==JSON.stringify(simConditions(plan.search))) ||
60	      validation.some((r,i)=>JSON.stringify(c(r))!==JSON.stringify(simConditions(plan.validation[i])))) throw Error('plan场景不符');
61	    if(new Set(validation.map(r=>JSON.stringify(r.gains))).size>1) throw Error('验证候选未冻结');
62	  }
63	  const feasible=searches.filter(r=>!r.metrics.fail && r.metrics.converged && Number.isFinite(r.metrics.j) &&
64	    (plan?.objective!=='impulse-recovery' || r.diagnostics?.disturbance?.recovered===true));
65	  const best=feasible.reduce((a,b)=>!a||b.metrics.j<a.metrics.j?b:a,null);
66	  const summary={verified:true,campaign,sourceHash:records[0].sourceHash,total:records.length,searches:searches.length,
67	    distinctSearchPoints:new Set(searches.map(r=>JSON.stringify(r.gains))).size,
68	    planComplete:plan?true:null,validationCount:validation.length,
69	    best:best?{runId:best.runId,gains:best.gains,j:best.metrics.j,converged:true}:null,
70	    controller:normalizeSimController(records[0].meta.sim.controller??{}),
71	    validationPassed:validation.length?validation.every(r=>!r.metrics.fail && r.metrics.converged &&
72	      (!r.meta.sim.disturbanceEvent || r.diagnostics?.disturbance?.recovered===true)):null,
73	    robustness:records.filter(r=>r.decision.purpose==='robustness').map(r=>({runId:r.runId,conditions:r.meta.sim,metrics:r.metrics,disturbanceRecovery:r.diagnostics?.disturbance??null}))};
74	  if(flags['--out']) {
75	    const out=resolve(flags['--out']);
76	    if(existsSync(out) || !relative(paths.runs,out).startsWith('..')) throw new Error('导出目录必须新建且在原始 runs 目录之外');
77	    mkdirSync(out,{recursive:true});
78	    for(const r of records) copyFileSync(resolve(paths.runs,r.csv),resolve(out,r.csv));
79	    writeFileSync(resolve(out,'index.jsonl'),records.map(r=>JSON.stringify(r)).join('\n')+'\n');
80	    writeFileSync(resolve(out,'summary.json'),JSON.stringify(summary,null,2)+'\n');
81	  }
82	  console.log(JSON.stringify(summary,null,2));
83	} catch(e) { console.error(JSON.stringify({verified:false,error:e.message})); process.exitCode=1; }

